+import events from './events.json' with {type:'json'};
+
+function encodeCursor(offset) {
+  return Buffer.from('offset:' + offset).toString('base64');
+}
+
+function decodeCursor(cursor) {
+  let decoded;
+  try {
+    decoded = Buffer.from(cursor, 'base64').toString('utf8');
+  } catch (e) {
+    throw new Error('Unknown cursor');
+  }
+  const match = /^offset:(\d+)$/.exec(decoded);
+  if (!match) {
+    throw new Error('Unknown cursor');
+  }
+  const offset = parseInt(match[1], 10);
+  if (offset < 0 || offset > events.length) {
+    throw new Error('Unknown cursor');
+  }
+  return offset;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'events_list',
+      description: 'List events in source order with cursor pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          cursor: {type: 'string'},
+          page_size: {type: 'integer', minimum: 1, maximum: 3}
+        },
+        required: [],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'events_list') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  args = args || {};
+  const allowed = new Set(['cursor', 'page_size']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error('Unknown argument: ' + key);
+    }
+  }
+
+  let offset = 0;
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('cursor must be a string');
+    }
+    offset = decodeCursor(args.cursor);
+  }
+
+  let pageSize = 2;
+  if (args.page_size !== undefined) {
+    if (typeof args.page_size !== 'number' || !Number.isInteger(args.page_size)) {
+      throw new Error('page_size must be an integer');
+    }
+    if (args.page_size < 1 || args.page_size > 3) {
+      throw new Error('page_size must be between 1 and 3');
+    }
+    pageSize = args.page_size;
+  }
+
+  const slice = events.slice(offset, offset + pageSize);
+  const hasMore = offset + pageSize < events.length;
+  const result = {
+    events: slice,
+    next_cursor: hasMore ? encodeCursor(offset + pageSize) : null
+  };
+
+  return {
+    content: [{type: 'text', text: JSON.stringify(result)}]
+  };
+}
